window.VO = [{"id":"n01","text":"You're the guard, and what you write in this register sends a man to jail.","at":0.24,"t0":0.12,"t1":3.965},{"id":"n02","text":"Flats on this street are being robbed, so ask this delivery man his name.","at":8.43,"t0":4.215,"t1":8.3},{"id":"a01","text":"Ravi, sir.","at":17,"t0":8.5,"t1":9.43},{"id":"n03","text":"Write it down, and ask which flat.","at":19.16,"t0":9.58,"t1":11.385},{"id":"b01","text":"Three zero two.","at":23.07,"t0":11.535,"t1":12.73},{"id":"n04","text":"Write that too, but anyone can say a flat number, so check his parcel.","at":25.86,"t0":12.93,"t1":17.03},{"id":"c01","text":"Here it is, sir.","at":34.36,"t0":17.18,"t1":18.235},{"id":"n05","text":"Does the label match your register?","at":36.87,"t0":18.435,"t1":20.215},{"id":"n06","text":"It doesn't. Good catch.","at":42.83,"t0":21.415,"t1":22.745},{"id":"d01","text":"Sorry, sir. I'll call the customer.","at":45.99,"t0":22.995,"t1":25.06},{"id":"n07","text":"So nobody got past you.","at":50.82,"t0":25.41,"t1":26.885},{"id":"n08","text":"Then who robbed flat three zero two?","at":54.17,"t0":27.085,"t1":28.99},{"id":"n09","text":"Police have four men in that jacket, but your register says one came, so point him out.","at":58.38,"t0":29.19,"t1":34.15},{"id":"n10","text":"He goes to jail, and the other three go home.","at":68.7,"t0":34.35,"t1":36.87},{"id":"n11","text":"Which one? You looked right at him.","at":74.14,"t0":37.07,"t1":38.895},{"id":"n12","text":"You're right. He was at your gate, and so were the other three.","at":81.99,"t0":40.995,"t1":44.05},{"id":"n13","text":"Every time you looked down, one walked in and the next stepped up, and you carried on.","at":89.6,"t0":44.8,"t1":49.095},{"id":"n14","text":"So three of them go home. Four, if you said none.","at":98.79,"t0":49.395,"t1":52.205},{"id":"n15","text":"Psychologists once swapped a man in a hard hat for another, and one woman who missed it said she'd just seen a construction worker.","at":105.21,"t0":52.605,"t1":59.54},{"id":"n16","text":"And these four aren't even delivery men. You just saw a jacket.","at":119.68,"t0":59.84,"t1":63.3},{"id":"n17","text":"Your register says Ravi.","at":127.5,"t0":63.75,"t1":65.2},{"id":"n18","text":"So which one was Ravi?","at":130.8,"t0":65.4,"t1":66.73}];
